import{_ as t,o as n,c as s,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-29（量子物理 / 强场物理 · 石墨烯子周期能带录像）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/quantum-physics/science-daily-2026-10-29-quantum.md","filePath":"topics/quantum-physics/science-daily-2026-10-29-quantum.md"}'),r={name:"topics/quantum-physics/science-daily-2026-10-29-quantum.md"};function a(c,o,i,d,l,g){return n(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="科学日报-·-2026-10-29-量子物理-强场物理-·-石墨烯子周期能带录像" tabindex="-1">科学日报 · 2026-10-29（量子物理 / 强场物理 · 石墨烯子周期能带录像） <a class="header-anchor" href="#科学日报-·-2026-10-29-量子物理-强场物理-·-石墨烯子周期能带录像" aria-label="Permalink to &quot;科学日报 · 2026-10-29（量子物理 / 强场物理 · 石墨烯子周期能带录像）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> — 第48期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-quantum</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-29-石墨烯的「子周期录像」——直接拍到非绝热-landau–zener–majorana-隧穿" tabindex="-1">科学日报 2026-10-29：石墨烯的「子周期录像」——直接拍到非绝热 Landau–Zener–Majorana 隧穿 <a class="header-anchor" href="#科学日报-2026-10-29-石墨烯的「子周期录像」——直接拍到非绝热-landau–zener–majorana-隧穿" aria-label="Permalink to &quot;科学日报 2026-10-29：石墨烯的「子周期录像」——直接拍到非绝热 Landau–Zener–Majorana 隧穿&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ DOI: 10.1038/s41586-026-11214-y ｜ Nature (2026)</p></blockquote><ul><li>问题：强光场能<strong>全光地</strong>裁剪电子的相干轨迹、改写能带乃至塑造物态；但要看懂机制，需要在<strong>能带里直接可视化光波驱动的电子运动</strong>。此前<strong>光电子动量显微</strong>只能拍<strong>多周期平均</strong>的激发电子，<strong>子周期能带录像</strong>又限于<strong>小动量</strong>。</li><li>方法：提出<strong>阿秒精度、覆盖整个第一布里渊区</strong>的<strong>子周期能带录像（subcycle videography）</strong>。</li><li>结果（实测）： <ul><li>可视化最基础却难捉摸的强场过程——<strong>非绝热 Landau–Zener–Majorana（LZM）隧穿</strong>：强场在<strong>石墨烯类狄拉克能带</strong>内的<strong>加速</strong>与<strong>周期性 LZ 带间隧穿</strong>交织；</li><li>表现为<strong>布里渊区边缘载流子分布的相干子周期位移与畸变</strong>；</li><li>这种极端<strong>非热（non-thermal）<strong>电子分布，让作者把</strong>相互竞争的散射过程分离出来</strong>、评估它们对<strong>相干电子控制</strong>的影响。</li></ul></li><li>洞察（对本库 <code>quantum-physics</code> × <code>physics</code>）： <ol><li><strong>「测得更全」本身就是新的物理能力</strong> —— 从「多周期平均 + 小动量」升级到「<strong>子周期 + 全布里渊区</strong>」，才让 <strong>LZM 隧穿</strong>从理论过程变成<strong>可视化对象</strong>。判据：<strong>当一个效应在时间或动量上被「平均掉」时，先想能不能把分辨率提上去（全时空观测），而不是换模型去拟合平均结果。</strong> 这与 10-25 STM 直接成像广义 Wigner 晶体、10-20 位移电流散粒噪声读出光子统计同族——<strong>「观测分辨率」是物理发现的独立前沿。</strong></li><li><strong>「极端非热分布 + 可分离散射」= 强场控制的诊断基石</strong> —— 只有先把<strong>竞争散射过程</strong>分离并量化，才能判断<strong>相干控制</strong>能走多远。可迁移判据：<strong>评估一个「相干操控」方案的上限时，先量化非相干通道（散射）的贡献，再谈相干能效。</strong></li><li><strong>一句话定位</strong>：本条把强场物理从「<strong>能操控</strong>」推进到「<strong>能看见操控过程</strong>」——与本库 <code>quantum-physics</code> 主线（纠缠/超导/量子精密计量）互补：多了一类<strong>超快时间尺度的能带观测工具</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/quantum-physics/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第48期 科学板块</p></blockquote><p>关键词：科学日报第48期、子周期能带录像、subcycle videography、阿秒精度、attosecond、第一布里渊区、石墨烯狄拉克能带、非绝热 Landau-Zener-Majorana 隧穿、LZM、强场物理、光电子动量显微、多周期平均、相干子周期位移、非热电子分布、竞争散射过程分离、相干电子控制、观测分辨率即发现前沿、Floquet-Bloch</p><p>关联：<code>topics/quantum-physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-10-28-quantum.md</code>（测量诱导压缩光干涉仪）、<code>topics/quantum-physics/science-daily-2026-10-25-quantum.md</code>（莫尔 Wigner 晶体的量子融化）、<code>topics/physics/index.md</code>、<code>topics/materials/science-daily-2026-10-29-materials.md</code></p>',10)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
